package postman_test

import (
	"encoding/json"
	"testing"

	"github.com/akyrey/postman-sync/internal/postman"
)

// mergeOneWithBase merges a single leaf request using a baseline (the request
// generated by the previous sync).
func mergeOneWithBase(t *testing.T, oldReq, baseReq, newReq string) *postman.Request {
	t.Helper()
	old := []postman.CollectionItem{{Name: "R", Request: decodeRequest(t, oldReq)}}
	base := []postman.CollectionItem{{Name: "R", Request: decodeRequest(t, baseReq)}}
	new := []postman.CollectionItem{{Name: "R", Request: decodeRequest(t, newReq)}}
	opts := postman.MergeOptions{PreserveRequestData: true, Baseline: base}
	return postman.MergeItemsWith(old, new, opts)[0].Request
}

// ── Headers / params ──────────────────────────────────────────────────────────

func TestMergeBaseline_UntouchedHeaderFollowsSpec(t *testing.T) {
	got := mergeOneWithBase(t,
		`{"header":[{"key":"A","value":"<string>","description":"a"}]}`,
		`{"header":[{"key":"A","value":"<string>","description":"a"}]}`,
		`{"header":[{"key":"A","value":"<integer>","description":"a","disabled":true}]}`,
	)

	if got.Header[0].Value != "<integer>" || !got.Header[0].Disabled {
		t.Errorf("untouched header should follow spec, got %+v", got.Header[0])
	}
}

func TestMergeBaseline_EditedHeaderIsKept(t *testing.T) {
	got := mergeOneWithBase(t,
		`{"header":[{"key":"A","value":"mine","description":"a"}]}`,
		`{"header":[{"key":"A","value":"<string>","description":"a"}]}`,
		`{"header":[{"key":"A","value":"<integer>","description":"a"}]}`,
	)

	if got.Header[0].Value != "mine" {
		t.Errorf("edited header value should be kept, got %+v", got.Header[0])
	}
}

func TestMergeBaseline_ValueAndDisabledAreIndependent(t *testing.T) {
	// The user only toggled the param on; its value was never edited.
	got := mergeOneWithBase(t,
		`{"url":{"query":[{"key":"page","value":"1","description":"p"}]}}`,
		`{"url":{"query":[{"key":"page","value":"1","description":"p","disabled":true}]}}`,
		`{"url":{"query":[{"key":"page","value":"<integer>","description":"p","disabled":true}]}}`,
	)

	q := got.URL.Query[0]
	if *q.Value != "<integer>" || q.Disabled {
		t.Errorf("want spec value and user's enabled state, got %s", toJSON(t, q))
	}
}

func TestMergeBaseline_SpecRemovedEntryWithoutDescriptionIsDropped(t *testing.T) {
	got := mergeOneWithBase(t,
		`{"header":[{"key":"Accept","value":"application/json"},{"key":"A","value":"a","description":"a"}]}`,
		`{"header":[{"key":"Accept","value":"application/json"},{"key":"A","value":"a","description":"a"}]}`,
		`{"header":[{"key":"A","value":"a","description":"a"}]}`,
	)

	if !equalStrings(headerKeys(got.Header), []string{"A"}) {
		t.Errorf("headers = %+v", got.Header)
	}
}

func TestMergeBaseline_HandAddedEntryWithDescriptionIsKept(t *testing.T) {
	got := mergeOneWithBase(t,
		`{"header":[{"key":"A","value":"a","description":"a"},{"key":"X-Mine","value":"1","description":"my note"}]}`,
		`{"header":[{"key":"A","value":"a","description":"a"}]}`,
		`{"header":[{"key":"A","value":"a","description":"a"}]}`,
	)

	if !equalStrings(headerKeys(got.Header), []string{"A", "X-Mine"}) {
		t.Errorf("headers = %+v", got.Header)
	}
}

func TestMergeBaseline_HandDeletedEntryStaysDeleted(t *testing.T) {
	got := mergeOneWithBase(t,
		`{"url":{"query":[{"key":"a","value":"1","description":"a"}]}}`,
		`{"url":{"query":[{"key":"a","value":"1","description":"a"},{"key":"b","value":"2","description":"b"}]}}`,
		`{"url":{"query":[{"key":"a","value":"1","description":"a"},{"key":"b","value":"2","description":"b"}]}}`,
	)

	if len(got.URL.Query) != 1 || *got.URL.Query[0].Key != "a" {
		t.Errorf("query = %s", toJSON(t, got.URL.Query))
	}
}

func TestMergeBaseline_PathVariablesFollowSpecUnlessEdited(t *testing.T) {
	got := mergeOneWithBase(t,
		`{"url":{"variable":[{"key":"id","value":"42"},{"key":"slug","value":"<string>"}]}}`,
		`{"url":{"variable":[{"key":"id","value":"<long>"},{"key":"slug","value":"<string>"}]}}`,
		`{"url":{"variable":[{"key":"id","value":"<integer>"},{"key":"slug","value":"<uuid>"}]}}`,
	)

	v := got.URL.Variable
	if v[0].Value != "42" || v[1].Value != "<uuid>" {
		t.Errorf("variables = %s", toJSON(t, v))
	}
}

func TestMergeBaseline_UntouchedFormFieldFollowsSpec(t *testing.T) {
	got := mergeOneWithBase(t,
		`{"body":{"mode":"formdata","formdata":[{"key":"a","value":"<string>","type":"text","description":"a"},{"key":"b","value":"mine","type":"text","description":"b"}]}}`,
		`{"body":{"mode":"formdata","formdata":[{"key":"a","value":"<string>","type":"text","description":"a"},{"key":"b","value":"<string>","type":"text","description":"b"}]}}`,
		`{"body":{"mode":"formdata","formdata":[{"key":"a","value":"<long>","type":"text","description":"a"},{"key":"b","value":"<long>","type":"text","description":"b"}]}}`,
	)

	f := got.Body.FormData
	if string(f[0].Extra["value"]) != `"<long>"` || string(f[1].Extra["value"]) != `"mine"` {
		t.Errorf("formdata = %s", toJSON(t, f))
	}
}

// ── Raw JSON body ─────────────────────────────────────────────────────────────

func TestMergeBaseline_RawBodyThreeWay(t *testing.T) {
	old := `{"untouched":"<string>","edited":"mine","spec_removed":"x","mine":true,"nested":{"a":"<string>","b":"kept"}}`
	base := `{"untouched":"<string>","edited":"<string>","spec_removed":"x","user_deleted":"<string>","nested":{"a":"<string>","b":"<string>"}}`
	new := `{"untouched":"<integer>","edited":"<integer>","user_deleted":"<integer>","nested":{"a":"<long>","b":"<long>"},"added":"<string>"}`
	got := mergeOneWithBase(t,
		`{"body":{"mode":"raw","raw":`+toJSON(t, old)+`}}`,
		`{"body":{"mode":"raw","raw":`+toJSON(t, base)+`}}`,
		`{"body":{"mode":"raw","raw":`+toJSON(t, new)+`}}`,
	)

	want := "{\n" +
		"  \"untouched\": \"<integer>\",\n" +
		"  \"edited\": \"mine\",\n" +
		"  \"nested\": {\n" +
		"    \"a\": \"<long>\",\n" +
		"    \"b\": \"kept\"\n" +
		"  },\n" +
		"  \"added\": \"<string>\",\n" +
		"  \"mine\": true\n" +
		"}"
	if got.Body.Raw != want {
		t.Errorf("raw body:\n%s\nwant:\n%s", got.Body.Raw, want)
	}
}

func TestMergeBaseline_UntouchedRawBodyIsReplacedVerbatim(t *testing.T) {
	newRaw := "{\n    \"id\": \"<long>\"\n}"
	got := mergeOneWithBase(t,
		`{"body":{"mode":"raw","raw":"{\"id\":\"<string>\"}"}}`,
		`{"body":{"mode":"raw","raw":"{\"id\":\"<string>\"}"}}`,
		`{"body":{"mode":"raw","raw":`+toJSON(t, newRaw)+`}}`,
	)

	if got.Body.Raw != newRaw {
		t.Errorf("raw body = %q, want %q", got.Body.Raw, newRaw)
	}
}

func TestMergeBaseline_UntouchedNonJSONBodyFollowsSpec(t *testing.T) {
	got := mergeOneWithBase(t,
		`{"body":{"mode":"raw","raw":"<xml/>"}}`,
		`{"body":{"mode":"raw","raw":"<xml/>"}}`,
		`{"body":{"mode":"raw","raw":"<xml v=\"2\"/>"}}`,
	)

	if got.Body.Raw != `<xml v="2"/>` {
		t.Errorf("raw body = %q", got.Body.Raw)
	}
}

// ── Baseline lookup ───────────────────────────────────────────────────────────

func TestMergeBaseline_MissingRequestFallsBackToTwoWay(t *testing.T) {
	old := []postman.CollectionItem{{Name: "R", Request: decodeRequest(t, `{"header":[{"key":"A","value":"<string>","description":"a"}]}`)}}
	new := []postman.CollectionItem{{Name: "R", Request: decodeRequest(t, `{"header":[{"key":"A","value":"<integer>","description":"a"}]}`)}}
	base := []postman.CollectionItem{{Name: "Other", Request: decodeRequest(t, `{}`)}}

	got := postman.MergeItemsWith(old, new, postman.MergeOptions{PreserveRequestData: true, Baseline: base})
	if got[0].Request.Header[0].Value != "<string>" {
		t.Errorf("without a baseline entry the old value should be kept, got %+v", got[0].Request.Header)
	}
}

func TestMergeBaseline_UsesBaselineInsideFolders(t *testing.T) {
	leaf := func(value string) postman.CollectionItem {
		return postman.CollectionItem{Name: "R", Request: decodeRequest(t, `{"header":[{"key":"A","value":"`+value+`","description":"a"}]}`)}
	}
	old := []postman.CollectionItem{folderItem("F", leaf("<string>"))}
	base := []postman.CollectionItem{folderItem("F", leaf("<string>"))}
	new := []postman.CollectionItem{folderItem("F", leaf("<integer>"))}

	got := postman.MergeItemsWith(old, new, postman.MergeOptions{PreserveRequestData: true, Baseline: base})
	if v := (*got[0].Items)[0].Request.Header[0].Value; v != "<integer>" {
		t.Errorf("nested untouched header should follow spec, got %q", v)
	}
}

func TestMergeBaseline_FormFieldComparisonIgnoresJSONEscaping(t *testing.T) {
	// Baselines are written by encoding/json, which may escape "<" as \u003c,
	// while Postman returns the literal character.
	field := func(value string) postman.FormParam {
		return postman.FormParam{Key: "a", Type: "text", Extra: postman.Extra{
			"value":       json.RawMessage(value),
			"description": json.RawMessage(`"a"`),
		}}
	}
	request := func(f postman.FormParam) *postman.Request {
		return &postman.Request{Body: &postman.Body{Mode: "formdata", FormData: []postman.FormParam{f}}}
	}
	old := []postman.CollectionItem{{Name: "R", Request: request(field(`"<string>"`))}}
	base := []postman.CollectionItem{{Name: "R", Request: request(field(`"\u003cstring\u003e"`))}}
	new := []postman.CollectionItem{{Name: "R", Request: request(field(`"<long>"`))}}

	got := postman.MergeItemsWith(old, new, postman.MergeOptions{PreserveRequestData: true, Baseline: base})
	if v := string(got[0].Request.Body.FormData[0].Extra["value"]); v != `"<long>"` {
		t.Errorf("untouched form value should follow spec, got %s", v)
	}
}
